import{_ as e,o as d,c as a,a2 as r}from"./chunks/framework.BW2T23B9.js";const p=JSON.parse('{"title":"课程结构","description":"","frontmatter":{},"headers":[],"relativePath":"guide/curriculum.md","filePath":"guide/curriculum.md","lastUpdated":null}'),i={name:"guide/curriculum.md"};function l(n,t,h,o,c,s){return d(),a("div",null,[...t[0]||(t[0]=[r('<h1 id="课程结构" tabindex="-1">课程结构 <a class="header-anchor" href="#课程结构" aria-label="Permalink to &quot;课程结构&quot;">​</a></h1><p>土耳其语课程按 CEFR 分成 8 个 Section（A1→B2）。每个 Section 下是主题 Unit，Unit 下是约 5 分钟一节的 Lesson，并按先修关系解锁。</p><p>产品页演示见 <a href="./../../curriculum.html">curriculum.html</a>。</p><h2 id="当前规模" tabindex="-1">当前规模 <a class="header-anchor" href="#当前规模" aria-label="Permalink to &quot;当前规模&quot;">​</a></h2><p>内容仍在缓慢扩充。当前土耳其语课大约是：</p><table tabindex="0"><thead><tr><th>项</th><th style="text-align:right;">数量</th></tr></thead><tbody><tr><td>分级 Section</td><td style="text-align:right;">8</td></tr><tr><td>主题 Unit</td><td style="text-align:right;">11</td></tr><tr><td>课时</td><td style="text-align:right;">54</td></tr><tr><td>词汇</td><td style="text-align:right;">148</td></tr><tr><td>表达</td><td style="text-align:right;">18</td></tr><tr><td>配套音频</td><td style="text-align:right;">37</td></tr><tr><td>语法点</td><td style="text-align:right;">8</td></tr></tbody></table><p>完整词表和引用关系在应用仓库的 <code>docs/content_inventory_current.md</code>，由导出脚本根据课程 JSON 生成，不在本站维护一份副本。</p><h2 id="分级" tabindex="-1">分级 <a class="header-anchor" href="#分级" aria-label="Permalink to &quot;分级&quot;">​</a></h2><table tabindex="0"><thead><tr><th>级别</th><th>含义</th><th>Section</th></tr></thead><tbody><tr><td>A1</td><td>入门</td><td>1–2</td></tr><tr><td>A2</td><td>基础</td><td>3–4</td></tr><tr><td>B1</td><td>进阶</td><td>5–6</td></tr><tr><td>B2</td><td>自如</td><td>7–8</td></tr></tbody></table><p>较低等级要达到一定掌握度后，才会解锁下一等级，对应可理解输入里的 i+1：先接触略高于当前水平的内容。</p><h2 id="题目形态" tabindex="-1">题目形态 <a class="header-anchor" href="#题目形态" aria-label="Permalink to &quot;题目形态&quot;">​</a></h2><p>课程里会出现认词卡、单选 / 多选、填空、句子翻译、听音选词、听写、听音理解等。它们都是检索练习，而不只是「考试」。</p><h2 id="下一步" tabindex="-1">下一步 <a class="header-anchor" href="#下一步" aria-label="Permalink to &quot;下一步&quot;">​</a></h2><ul><li><a href="/docs/guide/lesson-types">六种课型</a></li><li><a href="/docs/authoring/teacher-guide">教师如何改一课</a></li></ul>',14)])])}const g=e(i,[["render",l]]);export{p as __pageData,g as default};
